// Create Header component
function makeHeader(current) {
  const h = figma.createFrame();
  h.name = "Header";
  h.resize(1440, 100);
  h.fills = [{type:"SOLID", color:{r:0.13,g:0.13,b:0.15}}]; // dark band
  h.itemSpacing = 0;

  // Wordmark
  const wm = figma.createText();
  wm.characters = "{Inkline";
  wm.fontName = {family:"Sen", style:"Bold"};
  wm.fontSize = 26;
  wm.fills = [{type:"SOLID", color:{r:1,g:1,b:1}}];
  wm.x = 80; wm.y = 34;
  h.appendChild(wm);

  // Navigation
  const navItems = ["Home","Blog","About Us","Contact us"];
  const links = {"Home":0,"Blog":1,"About Us":2,"Contact us":3};
  let x = 700;
  for (let i=0;i<navItems.length;i++){
    const t = figma.createText();
    t.characters = navItems[i];
    t.fontName = {family:"Inter", style:"Regular"};
    t.fontSize = 16;
    t.fills = [{type:"SOLID", color:{r:1,g:1,b:1}}];
    t.x = x; t.y = 40;
    h.appendChild(t);
    // underline for current
    if (navItems[i]===current) {
      const u = figma.createRectangle();
      u.name = "CurrentUnderline";
      u.resize(t.width+8, 2);
      u.fills = [{type:"SOLID", color:{r:1,g:0.82,b:0.31}}]; // yellow
      u.x = x-4; u.y = 78;
      h.appendChild(u);
    }
    x += t.width + 40;
  }
  // Subscribe button (reuse Button component)
  const btn = await figma.importComponentByKeyAsync ? null : null;
  // Create subscribe button manually as yellow pill
  const sb = figma.createFrame();
  sb.name = "SubscribeButton";
  sb.resize(130, 56);
  sb.fills = [{type:"SOLID", color:{r:1,g:0.82,b:0.31}}]; // yellow
  sb.cornerRadius = 8;
  sb.x = 1225; sb.y = 22;
  h.appendChild(sb);
  const sbt = figma.createText();
  sbt.characters = "Subscribe";
  sbt.fontName = {family:"Inter", style:"Semi Bold"};
  sbt.fontSize = 16;
  sbt.fills = [{type:"SOLID", color:{r:0.14,g:0.15,b:0.21}}];
  sbt.x = sb.x + (130 - 78)/2; sbt.y = 22 + (56-20)/2;
  h.appendChild(sbt);
  return h;
}

