// Compute actual content bottom per frame (max of child.y+child.height) and trim frame heights
async function process(id){
  const f = await figma.getNodeByIdAsync(id);
  let maxBottom = 0;
  function walk(n){
    if(n.children){ for(const c of n.children){ maxBottom = Math.max(maxBottom, c.y + c.height); walk(c); } }
  }
  walk(f);
  // content bottom (absolute) = maxBottom since children coords are relative to frame
  const newH = Math.ceil(maxBottom + 20);
  const oldH = f.height;
  f.resize(f.width, newH);
  return {id, oldH, newH, maxBottom:Math.ceil(maxBottom)};
}
