// Apply "current" nav highlight to each screen's Header instance
const YELLOW = { r:1, g:0.8157, b:0.3137 }; // #FFD050

// map screen -> which nav item is current ("" = none)
const currentMap = {
  "01_Home": "Home",
  "02_Blog": "Blog",
  "03_Blog_Post": "Blog",
  "04_About_Us": "About Us",
  "05_Category_Business": "Blog",
  "06_Author": "",
  "07_Contact": "Contact us",
  "08_Privacy_Policy": ""
};

const page = await figma.getNodeByIdAsync("3:2");
const out = [];
for (const child of page.children) {
  if (child.type !== "FRAME") continue;
  const current = currentMap[child.name];
  // find Header instance in this screen
  let headerInst = null;
  function findHeader(n){
    if(n.type === "INSTANCE" && n.name === "Header"){ headerInst = n; return; }
    if(n.children){ for(const c of n.children) findHeader(c); }
  }
  findHeader(child);
  if (!headerInst) { out.push({screen:child.name, error:"no header"}); continue; }
  const applied = [];
  // override nav text fill via instance children
  if (current) {
    for (const c of headerInst.children) {
      if (c.type === "TEXT") {
        const t = c.characters;
        if (t === current) {
          c.fills = [{type:"SOLID", color:YELLOW}];
          applied.push(t+"->yellow");
        }
      }
    }
    // also add a small yellow underline bar under the current nav item
  }
  out.push({screen:child.name, applied});
}
return JSON.stringify(out);

