// Get header nav text nodes by name
async function findText(parent, name){
  const r = [];
  function walk(n){
    if(n.type==="TEXT" && n.name===name) r.push(n);
    if(n.children){ for(const c of n.children) walk(c); }
  }
  walk(parent);
  return r;
}

