// Reposition helper: given absolute child, move into banner with relative y
async function reparentInto(node, banner, relX, relY){
  // ensure it has proper fill if text
  banner.appendChild(node);
  node.x = relX;
  node.y = relY;
}

// Build Join Now button content for a banner
async function addJoinNowButton(banner){
  // check if already has a Frame button
  const btn = banner.children.find(c=>c.name==="Frame" && c.type==="FRAME");
  if(btn) return btn;
  const f = figma.createFrame();
  f.name="Frame";
  f.resize(180,56);
  f.x = 180;
  f.y = 170;
  f.fills=[{type:"SOLID", color:{r:1,g:0.82,b:0.31}, opacity:1}];
  f.cornerRadius=2;
  const t = figma.createText();
  t.characters="Join Now";
  t.fontName={family:"Sen", style:"Bold"};
  t.fontSize=18;
  t.x=45; t.y=16;
  t.fills=[{type:"SOLID", color:{r:0.11,g:0.12,b:0.34}, opacity:1}];
  f.appendChild(t);
  banner.appendChild(f);
  return f;
}

// Function to normalize a banner
async function normalizeBanner(banner){
  const h = banner.height;
  // heading relY, placeholder relY, button relY based on height
  let hy, py, by;
  if(h>=280){ hy=50; py=125; by=190; }
  else { hy=45; py=115; by=175; }
  // reposition existing text children
  for(const c of banner.children){
    if(c.type==="TEXT"){
      if(c.characters.startsWith("Join our team")){ c.x=180; c.y=hy; }
      else if(c.characters.startsWith("Lorem")){ c.x=180; c.y=py; }
    }
  }
  // move orphaned Home content into banner
  // add button
  await addJoinNowButton(banner);
}

