const orphans = [];
const toCheck = ["11:289","11:290","12:636","12:637"];
for(const id of toCheck){
  const n = await figma.getNodeByIdAsync(id);
  if(n){ try{ n.remove(); orphans.push({id,name:n.name,removed:true}); }catch(e){ orphans.push({id,error:String(e)}); } }
}
return JSON.stringify(orphans);

// Fix About page second-row authors (Guy, Eleanor, Robert, Jacob): content is 710px too low.
// Expected: avatar at frame.y+30, name at +190, title at +220, icons at +260
const rows = [
  {frame:"12:418", kids:["12:419","12:420","12:421","12:422","12:428","12:430","12:438"]},
  {frame:"12:444", kids:["12:445","12:446","12:447","12:448","12:454","12:456","12:464"]},
  {frame:"12:470", kids:["12:471","12:472","12:473","12:474","12:480","12:482","12:490"]},
  {frame:"12:496", kids:["12:497","12:498","12:499","12:500","12:506","12:508","12:516"]}
];
// target offsets per child role; but easier: shift all by -710 so avatar lands at 3065 (frame 3035+30)
const out=[];
for(const r of rows){
  const frame = await figma.getNodeByIdAsync(r.frame);
  if(!frame){ out.push({frame:r.frame, err:"no frame"}); continue; }
  // Determine intended offsets from first-row pattern: avatar +30, name +190, title +220, icons +260
  // Since all are currently ~710 too low relative to frame, shift each child so avatar = frame.y+30
  const avatar = await figma.getNodeByIdAsync(r.kids[0]);
  const delta = (frame.y + 38) - avatar.y; // avatar intended ~frame.y+38 (center-ish). Actually first row avatar at frame.y+30
  const delta2 = (frame.y + 30) - avatar.y;
  for(const kid of r.kids){
    const n = await figma.getNodeByIdAsync(kid);
    if(n) n.y += delta2;
  }
  out.push({frame:r.frame, delta2});
}
return JSON.stringify(out);

// Identify orphaned Join Now frames on Blog_Post(11:371,11:372), Author(13:541,13:542), Privacy(13:626,13:627)
// These are duplicates below the JoinBanner - remove them
const orphans = ["11:371","11:372","13:541","13:542","13:626","13:627"];
const out=[];
for(const id of orphans){
  const n = await figma.getNodeByIdAsync(id);
  if(n){ out.push({id,name:n.name,parent:n.parent?n.parent.name:"none"}); try{n.remove(); out[out.length-1].removed=true;}catch(e){out[out.length-1].err=String(e);} }
  else out.push({id, err:"not found"});
}
return JSON.stringify(out);

const about = await figma.getNodeByIdAsync("12:277");
const sections = about.children.map(c=>({name:c.name.slice(0,25), y:Math.round(c.y), h:Math.round(c.height), bottom:Math.round(c.y+c.height)}));
// author rows content bottom
const au = about.children.filter(c=>c.name.startsWith("Author_"));
const join = await figma.getNodeByIdAsync("12:522");
const footer = await figma.getNodeByIdAsync("12:527");
return JSON.stringify({
  frameH: Math.round(about.height),
  sections: sections,
  lastAuthorBottom: au.length? Math.round(Math.max(...au.map(a=>a.y+a.height))) : null,
  joinY: join? Math.round(join.y):null,
  footerY: footer? Math.round(footer.y):null
}, null, 1);

