const home = await figma.getNodeByIdAsync("10:40");
const band = home.children.find(c=>c.name==="AboutBand");
const bandId = band? band.id : null;
const homeH = Math.round(home.height);
const footer = home.children.find(c=>c.name==="Footer");
let bandKids=[];
if(band){ bandKids = band.children.map(c=>({name:c.name.slice(0,25), y:Math.round(c.y), chars:c.type==="TEXT"?c.characters.slice(0,30):""})); }
return JSON.stringify({bandId, homeH, footerBot: footer? Math.round(footer.y+footer.height):null, bandKids});

const cats=["10:79","10:85","10:101","10:113"];
const out=[];
for(const id of cats){
  const n=await figma.getNodeByIdAsync(id);
  out.push({id,name:n.name,x:Math.round(n.x),y:Math.round(n.y)});
}
return JSON.stringify(out);

// Comprehensive prototype reaction audit
const page = await figma.getNodeByIdAsync("3:2");
const frameNames = ["01_Home","02_Blog","03_Blog_Post","04_About_Us","05_Category_Business","06_Author","07_Contact","08_Privacy_Policy"];
const frameIds = {"01_Home":"10:40","02_Blog":"11:193","03_Blog_Post":"11:305","04_About_Us":"12:277","05_Category_Business":"12:541","06_Author":"13:493","07_Contact":"13:557","08_Privacy_Policy":"13:606"};

function destName(id){
  for(const [n,fid] of Object.entries(frameIds)){ if(fid===id) return n; }
  return id;
}

const report = {};
for(const name of frameNames){
  const f = await figma.getNodeByIdAsync(frameIds[name]);
  let links=[];
  function walk(n, parent){
    if(n.reactions && n.reactions.length>0){
      for(const r of n.reactions){
        for(const a of (r.actions||[])){
          if(a.destinationId){
            links.push({from: (parent||n.name).slice(0,30), to: destName(a.destinationId)});
          }
        }
      }
    }
    if(n.children) for(const c of n.children) walk(c, c.type==="INSTANCE"? c.name : parent);
  }
  walk(f, f.name);
  report[name] = links;
}
return JSON.stringify(report, null, 1);

